import React, { createContext, useContext, useState, useRef, ReactNode } from 'react';
import { Animated, Platform, StyleSheet, Text, TouchableOpacity, View, Vibration } from 'react-native';
import { MessageCircle, X } from 'lucide-react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { colors, spacing } from '../theme/colors';
import { Audio } from 'expo-av';
import { useRouter } from 'expo-router';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

// Re-use the glass ping sound we created
const SOUND_URI = 'data:audio/wav;base64,';

interface NotificationData {
  title: string;
  message: string;
  isPro?: boolean;
  onPress?: () => void;
}

interface NotificationContextType {
  showNotification: (data: NotificationData) => void;
}

const NotificationContext = createContext<NotificationContextType | null>(null);

export const useNotification = () => {
  const context = useContext(NotificationContext);
  if (!context) throw new Error('useNotification must be used within NotificationProvider');
  return context;
};

export const NotificationProvider = ({ children }: { children: ReactNode }) => {
  const [notification, setNotification] = useState<NotificationData | null>(null);
  const slideAnim = useRef(new Animated.Value(-150)).current;
  const insets = useSafeAreaInsets();
  const topOffset = Math.max(insets.top + 10, 50);
  const router = useRouter();

  const playSound = async () => {
    try {
      const { sound } = await Audio.Sound.createAsync({ uri: SOUND_URI });
      await sound.playAsync();
      setTimeout(() => sound.unloadAsync(), 2000);
    } catch (e) {
      console.log('Error playing sound', e);
    }
  };

  const showNotification = (data: NotificationData) => {
    setNotification(data);
    playSound();
    // Vibrate differently for PRO
    Vibration.vibrate(data.isPro ? [0, 50, 100, 50] : [0, 150]);

    slideAnim.setValue(-150);
    Animated.spring(slideAnim, {
      toValue: Platform.OS === 'ios' ? 65 : 45,
      tension: 50,
      friction: 7,
      useNativeDriver: true,
    }).start();

    setTimeout(() => closeNotification(), 4500);
  };

  const closeNotification = () => {
    Animated.timing(slideAnim, {
      toValue: -150,
      duration: 300,
      useNativeDriver: true,
    }).start(() => setNotification(null));
  };

  const handlePress = () => {
    if (notification?.onPress) {
      notification.onPress();
    } else {
      router.push('/messages');
    }
    closeNotification();
  };

  return (
    <NotificationContext.Provider value={{ showNotification }}>
      {children}
      
      {notification && notification.isPro && (
        <Animated.View style={[styles.toastContainer, { top: topOffset, transform: [{ translateY: slideAnim }] }]}>
          <TouchableOpacity activeOpacity={0.9} onPress={handlePress}>
            <LinearGradient colors={['#18181B', '#09090B']} style={styles.toastContent}>
              <LinearGradient colors={['#FDE047', '#F59E0B']} style={styles.toastGlowBar} />
              <LinearGradient colors={['rgba(253, 224, 71, 0.2)', 'rgba(245, 158, 11, 0.05)']} style={styles.toastIconWrapper}>
                <MessageCircle size={22} color="#FDE047" />
              </LinearGradient>
              <View style={styles.toastTextContainer}>
                <Text style={styles.toastTitle}>{notification.title}</Text>
                <Text style={styles.toastMessage} numberOfLines={2}>{notification.message}</Text>
              </View>
              <TouchableOpacity style={styles.closeBtn} onPress={closeNotification}>
                <X size={20} color="#6B7280" />
              </TouchableOpacity>
            </LinearGradient>
          </TouchableOpacity>
        </Animated.View>
      )}

      {notification && !notification.isPro && (
        <Animated.View style={[styles.toastContainer, { top: topOffset, transform: [{ translateY: slideAnim }] }]}>
          <TouchableOpacity activeOpacity={0.9} onPress={handlePress}>
            <View style={[styles.toastContent, styles.normalToastContent]}>
              <View style={styles.normalToastGlowBar} />
              <View style={[styles.toastIconWrapper, styles.normalToastIconWrapper]}>
                <MessageCircle size={22} color={colors.primary} />
              </View>
              <View style={styles.toastTextContainer}>
                <Text style={[styles.toastTitle, styles.normalToastTitle]}>{notification.title}</Text>
                <Text style={[styles.toastMessage, styles.normalToastMessage]} numberOfLines={2}>{notification.message}</Text>
              </View>
              <TouchableOpacity style={styles.closeBtn} onPress={closeNotification}>
                <X size={20} color="#9CA3AF" />
              </TouchableOpacity>
            </View>
          </TouchableOpacity>
        </Animated.View>
      )}
    </NotificationContext.Provider>
  );
};

const styles = StyleSheet.create({
  toastContainer: { position: 'absolute', left: spacing.md, right: spacing.md, zIndex: 99999 },
  toastContent: { flexDirection: 'row', alignItems: 'center', borderRadius: 22, padding: 18, paddingLeft: 22, shadowColor: '#F59E0B', shadowOffset: { width: 0, height: 12 }, shadowOpacity: 0.35, shadowRadius: 24, elevation: 16, borderWidth: 1, borderColor: 'rgba(253, 224, 71, 0.2)', overflow: 'hidden' },
  toastGlowBar: { position: 'absolute', left: 0, top: 0, bottom: 0, width: 4 },
  toastIconWrapper: { width: 48, height: 48, borderRadius: 24, justifyContent: 'center', alignItems: 'center', marginRight: 16, borderWidth: 1, borderColor: 'rgba(253, 224, 71, 0.3)' },
  toastTextContainer: { flex: 1, marginRight: 12 },
  toastTitle: { color: '#FDE047', fontSize: 15, fontWeight: '900', letterSpacing: 1, marginBottom: 4, textTransform: 'uppercase' },
  toastMessage: { color: '#D1D5DB', fontSize: 14, lineHeight: 20, fontWeight: '500' },
  closeBtn: { padding: 8, marginRight: -8 },
  normalToastContent: { backgroundColor: colors.white, borderColor: '#E5E7EB', shadowColor: '#000', shadowOpacity: 0.1, shadowRadius: 12, shadowOffset: { width: 0, height: 4 } },
  normalToastGlowBar: { position: 'absolute', left: 0, top: 0, bottom: 0, width: 4, backgroundColor: colors.primary },
  normalToastIconWrapper: { backgroundColor: 'rgba(16, 185, 129, 0.1)', borderColor: 'transparent' },
  normalToastTitle: { color: colors.primary, letterSpacing: 0 },
  normalToastMessage: { color: colors.text },
});
